import"./flows/local_web_approvals_after.js";import"./parent_access_template.js";import"chrome://resources/ash/common/cr_elements/cros_color_overrides.css.js";import"chrome://resources/ash/common/cr_elements/cr_button/cr_button.js";import"chrome://resources/cros_components/button/button.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{ExtensionApprovalsAfter}from"./flows/extension_approvals_after.js";import{LocalWebApprovalsAfterElement}from"./flows/local_web_approvals_after.js";import{getTemplate}from"./parent_access_after.html.js";import{isParentAccessJellyEnabled,ParentAccessEvent}from"./parent_access_app.js";import{ParentAccessParams_FlowType,ParentAccessResult}from"./parent_access_ui.mojom-webui.js";import{getParentAccessParams,getParentAccessUiHandler}from"./parent_access_ui_handler.js";class ParentAccessAfter extends PolymerElement{static get is(){return"parent-access-after"}static get template(){return getTemplate()}constructor(){super();this.parentAccessUiHandler=getParentAccessUiHandler()}ready(){super.ready();this.renderFlowSpecificContent();this.addEventListener(ParentAccessEvent.ON_SCREEN_SWITCHED,(()=>{if(isParentAccessJellyEnabled()){this.shadowRoot.querySelector("#action-button-jelly").focus()}else{this.shadowRoot.querySelector("#action-button").focus()}}))}async renderFlowSpecificContent(){const response=await getParentAccessParams();switch(response.params.flowType){case ParentAccessParams_FlowType.kWebsiteAccess:this.shadowRoot.querySelector("#after-screen-body").appendChild(new LocalWebApprovalsAfterElement);return;case ParentAccessParams_FlowType.kExtensionAccess:this.shadowRoot.querySelector("#after-screen-body").appendChild(new ExtensionApprovalsAfter);return;default:return}}onParentApproved(){this.parentAccessUiHandler.onParentAccessDone(ParentAccessResult.kApproved)}onParentDeclined(){this.parentAccessUiHandler.onParentAccessDone(ParentAccessResult.kDeclined)}}customElements.define(ParentAccessAfter.is,ParentAccessAfter);